(()=>{
const input=document.querySelector('#library-search'),chips=[...document.querySelectorAll('.filter-chip')],target=document.querySelector('#library-results'),count=document.querySelector('#library-count');let active='all';
function renderLibrary(){if(!input||!target)return;const q=input.value.trim().toLowerCase();const chosen=ARTICLE_CATALOG.filter(x=>(active==='all'||x.type===active)&&[x.title,x.topic,x.country||'',x.searchText||''].join(' ').toLowerCase().includes(q));if(count)count.textContent=chosen.length+'記事を表示';target.replaceChildren(...chosen.map(x=>{const a=document.createElement('a');a.className='library-entry';a.href='articles/'+x.slug+'.html';const meta=document.createElement('span');meta.className='library-topic';meta.textContent=(x.type==='diy'?'DIY':x.type==='infrastructure'?'土木・インフラ':x.type==='domestic'?'国内の技術':x.type==='inspection'?'劣化診断':x.type==='global'?'世界の事例':x.type==='tools'?'設備・電気の道具':'現場の工法')+' / '+(x.country?x.country+'・':'')+x.topic;const label=document.createElement('strong');label.textContent=x.title;const arrow=document.createElement('span');arrow.className='library-arrow';arrow.textContent='↗';a.append(meta,label,arrow);return a;}));if(!chosen.length)target.textContent='一致する記事がありません。言葉を短くしてお試しください。';}
if(input&&target){input.addEventListener('input',renderLibrary);chips.forEach(c=>c.addEventListener('click',()=>{active=c.dataset.filter;chips.forEach(b=>{b.classList.toggle('active',b===c);b.setAttribute('aria-pressed',String(b===c));});renderLibrary();}));const incoming=new URLSearchParams(location.search).get('q');if(incoming){input.value=incoming;renderLibrary();document.querySelector('#library')?.scrollIntoView();}else renderLibrary();}
const header=document.querySelector('.site-header .wrap');if(!header)return;const form=document.createElement('form');form.className='site-search';form.setAttribute('role','search');const box=document.createElement('input');box.type='search';box.name='q';box.placeholder='サイト内の記事を検索';box.setAttribute('aria-label','サイト内の記事を検索');box.autocomplete='off';const button=document.createElement('button');button.type='submit';button.textContent='検索';const results=document.createElement('div');results.className='site-search-results';results.setAttribute('role','listbox');results.hidden=true;form.append(box,button,results);const nav=header.querySelector('.nav');header.insertBefore(form,nav||null);const insideArticle=location.pathname.includes('/articles/'),base=insideArticle?'../':'';
function search(){const q=box.value.trim().toLocaleLowerCase();results.replaceChildren();if(!q){results.hidden=true;return [];}const found=ARTICLE_CATALOG.filter(x=>[x.title,x.topic,x.country||'',x.searchText||''].join(' ').toLocaleLowerCase().includes(q)).slice(0,8);for(const item of found){const a=document.createElement('a');a.className='site-search-result';a.setAttribute('role','option');a.href=base+'articles/'+item.slug+'.html';a.textContent=item.title+'　— '+item.topic;results.append(a);}if(!found.length){const msg=document.createElement('p');msg.className='site-search-empty';msg.textContent='該当する記事はありません。別の言葉で検索してください。';results.append(msg);}results.hidden=false;return found;}
box.addEventListener('input',search);box.addEventListener('focus',()=>{if(box.value.trim())search();});form.addEventListener('submit',e=>{e.preventDefault();const found=search();if(found.length===1){location.href=base+'articles/'+found[0].slug+'.html';return;}if(!insideArticle&&input){input.value=box.value;renderLibrary();document.querySelector('#library')?.scrollIntoView({behavior:'smooth'});results.hidden=true;return;}location.href=base+'./?q='+encodeURIComponent(box.value)+'#library';});document.addEventListener('click',e=>{if(!form.contains(e.target))results.hidden=true;});
})();
